import java.util.*;

class Solution {
  public List<String> binaryTreePaths(TreeNode root) {
    List<String> ans = new ArrayList<>();
    walk(root, "", ans);
    return ans;
  }

  private void walk(TreeNode node, String prefix, List<String> ans) {
    if (node == null) return;
    String path = prefix.isEmpty() ? String.valueOf(node.val) : prefix + "->" + node.val;
    if (node.left == null && node.right == null) ans.add(path);
    walk(node.left, path, ans);
    walk(node.right, path, ans);
  }
}
